package org.bukkit; public class Location implements Cloneable { World world; double x,y,z; public Location(World w,double x,double y,double z){world=w;this.x=x;this.y=y;this.z=z;} public World getWorld(){return world;} public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;} public void setX(double x){this.x=x;} public void setY(double y){this.y=y;}public void setZ(double z){this.z=z;} public Location clone(){return new Location(world,x,y,z);} }
